-- Insert Models & Rules
DO $$
DECLARE
    v_brand_id BIGINT;
    v_model_id BIGINT;
BEGIN
    SELECT id INTO v_brand_id FROM car_brands WHERE name = 'Acura';
    
    INSERT INTO car_models (brand_id, name) 
    VALUES (v_brand_id, 'EL') 
    ON CONFLICT (brand_id, name) DO UPDATE SET name = EXCLUDED.name
    RETURNING id INTO v_model_id;

    INSERT INTO car_classifier_rules (model_id, generation, segment, year_from, year_to, status_grade_a, status_grade_b)
    VALUES (v_model_id, '2 пок', 'C', 2001, NULL, 'RESTRICTED', 'STANDARD');
END $$;
